/bin/bash -lc "node --input-type=module <<'EOF'
import http from 'node:http';
import { createApp } from './src/server.js';
const server = http.createServer(createApp());
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const { port } = server.address();
const base = "'`http://127.0.0.1:${port}`;
const signIn = await fetch(`${base}/api/sign-in`, { method:'"'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({patientId:'patient-a'}) });
const cookie = signIn.headers.get('set-cookie')?.split(';')[0] ?? '';
const detail = await fetch("'`${base}/api/appointments/not-real`, { headers:{cookie} });
console.log(JSON.stringify({signIn: signIn.status, hasSessionCookie: Boolean(cookie), detailWithoutData: detail.status}));
server.close();
EOF'

